import{c as a,Q as s,j as t,m as i}from"./chunks/framework.W-g_WCNV.js";const k=JSON.parse('{"title":"Cross-domain ForwardAuth","description":"How GateKeeper authenticates users across apps on different domains or TLDs.","frontmatter":{"title":"Cross-domain ForwardAuth","description":"How GateKeeper authenticates users across apps on different domains or TLDs."},"headers":[],"relativePath":"integrations/cross-domain.md","filePath":"integrations/cross-domain.md"}'),o={name:"integrations/cross-domain.md"};function n(r,e,d,h,p,l){return s(),t("div",null,[...e[0]||(e[0]=[i(`<p>The standard Traefik ForwardAuth setup works seamlessly when all your apps share a common parent domain (for example <code>app.example.com</code> and <code>other.example.com</code> can both receive a cookie set on <code>.example.com</code>). When apps live on <strong>completely different domains</strong> (for example <code>app.example.com</code> and <code>app.otherdomain.io</code>), cookies set by GateKeeper cannot be shared across domains - this is a browser security constraint.</p><p>GateKeeper solves this with a single-use handoff token.</p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><ol><li>A user visits <code>app.otherdomain.io</code>. Traefik sends the verify request to GateKeeper.</li><li>GateKeeper sees there is no valid session for this host and redirects to <code>/login?redirect_uri=https://app.otherdomain.io/the-page</code>.</li><li>The user logs in on <code>auth.example.com</code>. GateKeeper checks the redirect target against its allowlist, then detects that it is outside the shared cookie domain.</li><li>GateKeeper creates a <strong>handoff token</strong>: a random value stored server-side, recorded against the user and the destination host, and valid for two minutes. The token is only a reference. It carries no session or user data.</li><li>The browser is sent to <code>https://app.otherdomain.io/_gk/auth?token=XXX&amp;redirect=/the-page</code>.</li><li>Traefik intercepts this request and forwards it to GateKeeper&#39;s verify endpoint.</li><li>GateKeeper redeems the token. Redemption succeeds only once, and only when the requesting host matches the host the token was issued for. GateKeeper then creates a <strong>new session</strong> for that user and sets a <code>gk_session</code> cookie scoped to <code>app.otherdomain.io</code> (no <code>Domain</code> attribute, so the browser scopes it to the exact host).</li><li>GateKeeper redirects back to <code>/the-page</code>. The user is now authenticated on <code>app.otherdomain.io</code> and future requests carry the host-scoped session cookie.</li></ol><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><p>Apps on a different domain than GateKeeper must be listed as allowed redirect destinations, otherwise sign-in returns the user to the GateKeeper home page instead of the app.</p><p>Add them in the admin panel under <strong>Settings - Access control - Protected app domains</strong>. Changes apply immediately, with no restart:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>jellyfin.otherdomain.io</span></span>
<span class="line"><span>.third.net</span></span></code></pre></div><p>Entries are one per line or comma-separated, and each one covers that domain and all of its subdomains. Listing <code>otherdomain.io</code> allows <code>jellyfin.otherdomain.io</code> and every other host under it. The forms <code>.otherdomain.io</code>, <code>*.otherdomain.io</code>, and a pasted URL are all equivalent.</p><p>Two groups of hosts are always allowed and never need an entry: your <code>BASE_URL</code> and <code>ADMIN_URL</code> hosts, and anything under <code>COOKIE_DOMAIN</code>.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">BASE_URL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">https://auth.example.com</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">COOKIE_DOMAIN</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.example.com</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # covers *.example.com without any extra setting</span></span></code></pre></div><p>The same list can also be pre-seeded with the <code>REDIRECT_ALLOWED_HOSTS</code> environment variable, which is useful for automated deployments. Entries from both sources are combined.</p><h2 id="token-security" tabindex="-1">Token security <a class="header-anchor" href="#token-security" aria-label="Permalink to &quot;Token security&quot;">​</a></h2><p>The handoff token is a reference to a server-side record, not a credential in itself:</p><ul><li><strong>No session data in the URL</strong> - the token is a random value. Reading it from a log or browser history reveals nothing about the session, and it cannot be turned into a session cookie for the auth domain.</li><li><strong>Single use</strong> - redemption is an atomic update. The second attempt with the same token always fails, so a captured token cannot be replayed even within its lifetime.</li><li><strong>Host-bound</strong> - a token issued for <code>app.otherdomain.io</code> is rejected if presented from any other host.</li><li><strong>Short-lived</strong> - unredeemed tokens expire after two minutes and are cleaned up in the background.</li><li><strong>Kept out of logs</strong> - GateKeeper&#39;s own ForwardAuth debug logging records the request path only, never the query string.</li></ul><h2 id="traefik-configuration" tabindex="-1">Traefik configuration <a class="header-anchor" href="#traefik-configuration" aria-label="Permalink to &quot;Traefik configuration&quot;">​</a></h2><p>The <code>/_gk/auth</code> path on each protected app&#39;s domain must be reachable by Traefik&#39;s ForwardAuth check. No special configuration is needed - the standard <code>gk-auth</code> middleware handles this path automatically.</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">http</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  middlewares</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    gk-auth</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      forwardAuth</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">        address</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;http://gatekeeper:8282/auth/verify&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">        authResponseHeaders</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">          - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">X-Auth-User</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">          - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">X-Auth-Email</span></span></code></pre></div><p>Point <code>address</code> directly at the GateKeeper container (<code>gatekeeper:8282</code>, a private IP, or a Tailscale address), not at the public <code>auth.example.com</code>. Routing the ForwardAuth request through the auth domain rewrites <code>X-Forwarded-Host</code> and breaks the cross-domain redirect back to the app.</p><p>Apply this middleware to routes on any domain, including domains unrelated to <code>example.com</code>. GateKeeper handles the cross-domain handoff transparently.</p>`,20)])])}const u=a(o,[["render",n]]);export{k as __pageData,u as default};
